style.css:
@-moz-document domain("roblox.com") {
/* General Background */
    body, html, .container, .content, .page-container {
        background-color: #080808 !important;
        color: #00ffea !important;
    }

    /* Header and Navbar */
    .navbar, .header, .topbar, .nav-menu {
        background: linear-gradient(90deg, #ff00ff, #00ffff) !important;
        border-bottom: 3px solid #ffea00 !important;
    }

    /* Buttons */
    .btn, .btn-primary, .btn-secondary, .btn-game {
        background: linear-gradient(45deg, #00ffea, #ff00ff) !important;
        color: #fff !important;
        border: 2px solid #fff !important;
        box-shadow: 0px 0px 10px #00ffea !important;
        transition: 0.3s ease-in-out;
    }

    .btn:hover {
        background: linear-gradient(45deg, #ff00ff, #00ffea) !important;
        box-shadow: 0px 0px 15px #ffea00 !important;
    }

    /* Game Cards */
    .game-card, .game-card-container, .game-card-thumb-container {
        background-color: #111 !important;
        border: 2px solid #ff00ff !important;
        box-shadow: 0px 0px 10px #00ffff !important;
    }

    /* Images - Neon Glow */
    img, .thumbnail, .avatar, .game-card-thumb, .profile-picture {
        filter: brightness(120%) contrast(110%) !important;
        box-shadow: 0px 0px 5px #ff00ff !important;
    }

    /* Sidebar & Dropdowns */
    .sidebar, .dropdown-menu, .modal-content {
        background: #080808 !important;
        color: #00ffea !important;
        border: 2px solid #ff00ff !important;
    }

    /* Chat & Messages */
    .chat-container, .chat-window, .message-container, .text-message {
        background: #000 !important;
        color: #00ffea !important;
        border: 1px solid #ff00ff !important;
    }

    /* Scrollbar - Cyberpunk Glow */
    ::-webkit-scrollbar {
        width: 12px;
    }

    ::-webkit-scrollbar-track {
        background: #000;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(45deg, #00ffea, #ff00ff);
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: linear-gradient(45deg, #ff00ff, #00ffea);
        box-shadow: 0px 0px 10px #ffea00;
    }
}
